const inputItems = $input.all();
const payload = $node['Code | Validate Telegram Message | CheckTelegramMessage'].json;
const config = $node['Set | Knowledge Base Config | PrepareObsidianKB'].json;

const tableName = String(config.obsidianKbTableName || 'Obsidian RAG Knowledge Base').trim();
const maxRowsToLoad = Number(config.maxRowsToLoad || 5000);
const maxCharsPerRow = Number(config.maxCharsPerRow || 6000);
const allowedItemTypes = new Set(String(config.allowedItemTypes || '')
  .split(',')
  .map(value => value.trim())
  .filter(Boolean));

function safeString(value) {
  return String(value ?? '').trim();
}

function cleanContent(value, maxChars) {
  const text = safeString(value)
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();

  return text.slice(0, maxChars);
}

function buildTitle(row) {
  const directTitle = safeString(row.title || row.noteTitle || row.fileTitle || row.name);
  if (directTitle) return directTitle;

  const path = safeString(row.relativePath || row.absolutePath || row.path);
  if (!path) return safeString(row.itemId || row.knowledgeId || row.id || 'Заметка без названия');

  return path
    .split(/[\\/]/)
    .pop()
    .replace(/\.md$/i, '')
    .replace(/_/g, ' ')
    .trim() || path;
}

function normalizeRow(row, index) {
  const itemType = safeString(row.itemType || row.type || 'atomic');
  const content = cleanContent(
    row.content ||
    row.markdown ||
    row.text ||
    row.body ||
    row.noteContent ||
    row.contentExcerpt ||
    '',
    maxCharsPerRow
  );

  return {
    rowId: safeString(row.rowId || row.id || row.knowledgeId || row.itemId || `kb_row_${index + 1}`),
    knowledgeId: safeString(row.knowledgeId || row.id || row.rowId || row.itemId || `kb_row_${index + 1}`),
    uploadId: safeString(row.uploadId || ''),
    tenantId: safeString(row.tenantId || ''),
    sourceTitle: safeString(row.sourceTitle || row.source || row.sourceName || ''),
    itemId: safeString(row.itemId || row.knowledgeId || row.id || `kb_row_${index + 1}`),
    itemType,
    relativePath: safeString(row.relativePath || row.path || ''),
    absolutePath: safeString(row.absolutePath || ''),
    contentHash: safeString(row.contentHash || row.hash || ''),
    title: buildTitle(row),
    importance: Number(row.importance ?? row.importanceScore ?? row.weight ?? 0),
    tags: safeString(row.tags || row.hashtags || ''),
    contentLength: Number(row.contentLength || content.length || 0),
    content
  };
}

function isErrorItem(item) {
  const row = item.json || {};
  return Boolean(row.error || row.message?.includes?.('error') || row.name === 'NodeApiError');
}

const firstErrorItem = inputItems.find(isErrorItem);
if (firstErrorItem) {
  const rawError = firstErrorItem.json?.error || firstErrorItem.json?.message || firstErrorItem.json;
  const errorMessage = `Не удалось прочитать Data Table "${tableName}". Проверь, что таблица создана и доступна в n8n.`;

  return [
    {
      json: {
        ...payload,
        obsidianReady: false,
        kbLoadMode: 'data_table',
        obsidianKbTableName: tableName,
        obsidianErrorMessage: errorMessage,
        error: errorMessage,
        diagnostics: {
          stage: 'PrepareObsidianKB',
          ok: false,
          error: errorMessage,
          rawError
        },
        kbStats: {
          kbLoadMode: 'data_table',
          obsidianKbTableName: tableName,
          totalRows: 0,
          loadedFiles: 0,
          skippedRows: 0,
          emptyContentRows: 0,
          itemTypes: {},
          sourceTitles: []
        },
        missingFiles: [],
        obsidianRows: []
      }
    }
  ];
}

const rawRows = inputItems
  .map(item => item.json || {})
  .filter(row => Object.keys(row).length > 0)
  .slice(0, maxRowsToLoad);

const itemTypes = {};
const sourceSet = new Set();
let skippedRows = 0;
let emptyContentRows = 0;

const rows = [];
for (let index = 0; index < rawRows.length; index++) {
  const normalized = normalizeRow(rawRows[index], index);

  if (allowedItemTypes.size > 0 && normalized.itemType && !allowedItemTypes.has(normalized.itemType)) {
    skippedRows += 1;
    continue;
  }

  if (!normalized.content) {
    emptyContentRows += 1;
    continue;
  }

  itemTypes[normalized.itemType] = (itemTypes[normalized.itemType] || 0) + 1;
  if (normalized.sourceTitle) sourceSet.add(normalized.sourceTitle);
  rows.push(normalized);
}

const sourceTitles = Array.from(sourceSet).slice(0, 100);
const obsidianReady = rows.length > 0;
const obsidianErrorMessage = obsidianReady
  ? ''
  : `В Data Table "${tableName}" нет пригодных строк базы знаний. Проверь, что индексатор заполнил поле content.`;

return [
  {
    json: {
      ...payload,
      obsidianReady,
      kbLoadMode: 'data_table',
      obsidianKbTableName: tableName,
      maxRowsToLoad,
      maxCharsPerRow,
      obsidianErrorMessage,
      kbStats: {
        kbLoadMode: 'data_table',
        obsidianKbTableName: tableName,
        totalRows: rawRows.length,
        loadedFiles: rows.length,
        skippedRows,
        emptyContentRows,
        sourceTitles,
        itemTypes
      },
      missingFiles: [],
      obsidianRows: rows
    }
  }
];

const input = $input.first().json;

const tableName = String(input.obsidianKbTableName || 'Obsidian RAG Knowledge Base').trim();
const errorMessage = String(
  input.obsidianErrorMessage ||
  input.error ||
  `База знаний Data Table "${tableName}" не загрузилась.`
).trim();

const answer = `База знаний Obsidian сейчас не доступна, поэтому я не могу ответить с учётом сохранённых заметок.

Причина: ${errorMessage}

Что проверить:
1. существует ли Data Table "${tableName}";
2. заполнена ли она строками базы знаний;
3. есть ли в строках поле content с текстом заметки;
4. если таблица пустая — запусти отдельный индексатор Obsidian, который загрузит CSV/Markdown в Data Table.`;

return [
  {
    json: {
      ...input,
      contextFound: false,
      selectedContextCount: 0,
      relevantNotes: [],
      contextStats: {
        stage: 'PrepareObsidianKB',
        contextFound: false,
        reason: 'knowledge_base_unavailable',
        obsidianReady: false,
        kbLoadMode: 'data_table',
        obsidianKbTableName: tableName,
        errorMessage
      },
      promptStats: {
        built: false,
        reason: 'knowledge_base_unavailable'
      },
      aiCallReady: false,
      aiResponseReady: true,
      aiFallbackUsed: true,
      aiErrorMessage: errorMessage,
      aiAnswer: answer,
      requestStatus: 'knowledge_base_unavailable',
      messageSkipReason: 'knowledge_base_unavailable'
    }
  }
];

const input = $input.first().json;
const question = String(input.question || '').trim();
const rows = Array.isArray(input.obsidianRows) ? input.obsidianRows : [];

const config = {
  maxRelevantNotes: Number(input.maxRelevantNotes || 6),
  minScore: Number(input.minContextScore || 8),
  minStrongScore: Number(input.minStrongContextScore || 16),
  maxExcerptChars: Number(input.maxContextExcerptChars || 1800),
  maxWeakNotes: 2,
  exactQuestionBonus: 35,
  titleTokenWeight: 9,
  sourceTokenWeight: 5,
  keywordTokenWeight: 8,
  tagTokenWeight: 7,
  contentTokenWeight: 2,
  searchTextTokenWeight: 3,
  bigramTitleWeight: 16,
  bigramContentWeight: 7,
  bigramKeywordWeight: 10
};

const stopWords = new Set([
  'это','как','что','чем','для','или','при','над','под','про','без','где','когда','если','там','тут','мне','тебе','нам','вам','они','она','оно','его','её','ему','моя','мой','мои','мое','свои','свой','все','всё','уже','еще','ещё','так','вот','надо','нужно','можно','какой','какая','какие','какое','почему','зачем','очень','более','менее','через','между','после','перед','либо','быть','была','было','были','есть','из','на','по','с','со','в','во','и','а','но','же','бы','ли','не','нет','да','то','за','от','до','у','к','ко','вообще','сейчас','потом','тогда','будет','надо','нужен','нужна','нужны','сделай','делай','расскажи','напиши','покажи','объясни',
  'the','and','for','with','from','this','that','what','how','why','where','when','are','was','were','is','to','of','in','on','or','as','by','be','an','a','do','does','did','can','could','should','would','need','make','show','tell','explain'
]);

const typeWeight = {
  atomic: 1.35,
  concept: 1.25,
  principle: 1.22,
  question: 1.18,
  report: 1.0,
  source_map: 0.78,
  index: 0.7,
  json: 0.55
};

const importanceWeight = {
  critical: 1.35,
  high: 1.22,
  medium: 1.0,
  normal: 1.0,
  low: 0.82,
  noise: 0.45
};

function normalize(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[`*_#>\[\](){}.,!?;:«»"'|\\/\-–—+=<>~$%^&@№]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function unique(values) {
  return [...new Set(values.filter(Boolean))];
}

function safeParseArray(value) {
  if (Array.isArray(value)) return value.map(String).filter(Boolean);
  const text = String(value || '').trim();
  if (!text) return [];
  try {
    const parsed = JSON.parse(text);
    if (Array.isArray(parsed)) return parsed.map(String).filter(Boolean);
  } catch (error) {}
  return text
    .split(/[;,|#\n]/g)
    .map(v => v.trim())
    .filter(Boolean);
}

function lightStem(token) {
  let t = String(token || '').toLowerCase().replace(/ё/g, 'е').trim();
  if (t.length <= 5) return t;
  t = t.replace(/(иями|ями|ами|ого|ему|ыми|ими|ая|яя|ое|ее|ые|ие|ый|ий|ой|ых|их|ую|юю|ам|ям|ах|ях|ов|ев|ом|ем|ою|ею|а|я|ы|и|у|ю|о|е)$/u, '');
  return t.length >= 3 ? t : token;
}

function tokenize(value) {
  const tokens = normalize(value)
    .split(' ')
    .map(token => token.trim())
    .filter(token => token.length >= 3 && !stopWords.has(token));

  const stemmed = tokens
    .map(lightStem)
    .filter(token => token.length >= 3 && !stopWords.has(token));

  return unique([...tokens, ...stemmed]);
}

function buildBigrams(tokens) {
  const baseTokens = unique(tokens).slice(0, 14);
  const result = [];
  for (let i = 0; i < baseTokens.length - 1; i++) {
    result.push(baseTokens[i] + ' ' + baseTokens[i + 1]);
  }
  return unique(result);
}

function countMatches(text, token, maxCount = 6) {
  if (!text || !token) return 0;
  let count = 0;
  let index = text.indexOf(token);
  while (index !== -1 && count < maxCount) {
    count += 1;
    index = text.indexOf(token, index + token.length);
  }
  return count;
}

function cleanSnippet(value, maxChars) {
  return String(value || '')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim()
    .slice(0, maxChars);
}

function buildExcerpt(content, keywords, maxChars) {
  const raw = String(content || '').trim();
  if (!raw) return '';
  const lower = raw.toLowerCase().replace(/ё/g, 'е');
  let bestIndex = -1;
  for (const keyword of keywords) {
    const normalizedKeyword = String(keyword || '').toLowerCase().replace(/ё/g, 'е').trim();
    if (!normalizedKeyword || normalizedKeyword.length < 3) continue;
    const index = lower.indexOf(normalizedKeyword);
    if (index !== -1 && (bestIndex === -1 || index < bestIndex)) {
      bestIndex = index;
    }
  }
  if (bestIndex === -1) return cleanSnippet(raw, maxChars);
  const start = Math.max(0, bestIndex - 450);
  const end = Math.min(raw.length, start + maxChars);
  const prefix = start > 0 ? '... ' : '';
  const suffix = end < raw.length ? ' ...' : '';
  return prefix + cleanSnippet(raw.slice(start, end), maxChars) + suffix;
}

function normalizeImportance(row) {
  const raw = String(row.importance || row.priority || '').toLowerCase().trim();
  if (!raw) return 'normal';
  if (['critical','критично','критическая','очень важно','очень_важно'].includes(raw)) return 'critical';
  if (['high','высокая','важно','важный'].includes(raw)) return 'high';
  if (['medium','средняя','нормальная','normal'].includes(raw)) return 'medium';
  if (['low','низкая','слабая'].includes(raw)) return 'low';
  if (['noise','мусор','мусорная'].includes(raw)) return 'noise';
  const numeric = Number(raw);
  if (Number.isFinite(numeric)) {
    if (numeric >= 80) return 'critical';
    if (numeric >= 60) return 'high';
    if (numeric >= 30) return 'medium';
    return 'low';
  }
  return 'normal';
}

function compactReason(parts) {
  return parts.filter(Boolean).slice(0, 8).join('; ');
}

const questionTokens = unique(tokenize(question));
const questionBigrams = buildBigrams(questionTokens);
const normalizedQuestion = normalize(question);
const questionIsShort = questionTokens.length <= 2;

const scoredRows = rows.map((row, index) => {
  const title = String(row.title || '');
  const sourceTitle = String(row.sourceTitle || '');
  const content = String(row.content || '');
  const searchText = String(row.searchText || '');
  const keywords = safeParseArray(row.keywords);
  const tags = safeParseArray(row.tags);
  const itemType = String(row.itemType || '').trim();
  const importance = normalizeImportance(row);

  const titleNorm = normalize(title);
  const sourceNorm = normalize(sourceTitle);
  const contentNorm = normalize(content);
  const searchTextNorm = normalize(searchText || content);
  const keywordsNorm = normalize(keywords.join(' '));
  const tagsNorm = normalize(tags.join(' '));

  const matchedKeywords = [];
  const matchDetails = [];
  let rawScore = 0;

  if (normalizedQuestion.length >= 14 && (contentNorm.includes(normalizedQuestion) || searchTextNorm.includes(normalizedQuestion))) {
    rawScore += config.exactQuestionBonus;
    matchDetails.push(`точное совпадение вопроса +${config.exactQuestionBonus}`);
  }

  for (const token of questionTokens) {
    let tokenScore = 0;
    if (titleNorm.includes(token)) tokenScore += config.titleTokenWeight;
    if (sourceNorm.includes(token)) tokenScore += config.sourceTokenWeight;
    if (keywordsNorm.includes(token)) tokenScore += config.keywordTokenWeight;
    if (tagsNorm.includes(token)) tokenScore += config.tagTokenWeight;

    const searchTextMatches = countMatches(searchTextNorm, token, 4);
    const contentMatches = countMatches(contentNorm, token, 5);
    if (searchTextMatches > 0) tokenScore += Math.min(searchTextMatches, 3) * config.searchTextTokenWeight;
    if (contentMatches > 0) tokenScore += Math.min(contentMatches, 4) * config.contentTokenWeight;

    if (tokenScore > 0) {
      matchedKeywords.push(token);
      rawScore += tokenScore;
      matchDetails.push(`${token} +${tokenScore}`);
    }
  }

  for (const bigram of questionBigrams) {
    let bigramScore = 0;
    if (titleNorm.includes(bigram)) bigramScore += config.bigramTitleWeight;
    if (keywordsNorm.includes(bigram)) bigramScore += config.bigramKeywordWeight;
    if (contentNorm.includes(bigram) || searchTextNorm.includes(bigram)) bigramScore += config.bigramContentWeight;
    if (bigramScore > 0) {
      rawScore += bigramScore;
      matchDetails.push(`фраза "${bigram}" +${bigramScore}`);
    }
  }

  const typeMultiplier = typeWeight[itemType] || 1;
  const importanceMultiplier = importanceWeight[importance] || 1;
  const shortQuestionPenalty = questionIsShort && matchedKeywords.length < 2 ? 0.72 : 1;
  const emptyContentPenalty = content.trim().length < 120 ? 0.65 : 1;

  const finalScore = Math.round(rawScore * typeMultiplier * importanceMultiplier * shortQuestionPenalty * emptyContentPenalty * 100) / 100;

  const rankReason = compactReason([
    rawScore ? `база ${Math.round(rawScore * 100) / 100}` : '',
    itemType ? `тип ${itemType} x${typeMultiplier}` : '',
    importance ? `важность ${importance} x${importanceMultiplier}` : '',
    shortQuestionPenalty !== 1 ? `штраф короткого вопроса x${shortQuestionPenalty}` : '',
    emptyContentPenalty !== 1 ? `штраф пустого контента x${emptyContentPenalty}` : '',
    ...matchDetails.slice(0, 4)
  ]);

  return {
    ...row,
    originalIndex: index,
    relevanceScore: finalScore,
    rawRelevanceScore: Math.round(rawScore * 100) / 100,
    importance,
    matchedKeywords: unique(matchedKeywords),
    matchedKeywordCount: unique(matchedKeywords).length,
    rankReason,
    matchDetails: matchDetails.slice(0, 20),
    keywords,
    tags,
    contentExcerpt: buildExcerpt(content, unique([...matchedKeywords, ...questionBigrams, ...keywords.slice(0, 5)]), config.maxExcerptChars)
  };
});

const positiveRows = scoredRows
  .filter(row => row.relevanceScore >= config.minScore)
  .sort((a, b) => {
    if (b.relevanceScore !== a.relevanceScore) return b.relevanceScore - a.relevanceScore;
    if ((b.matchedKeywordCount || 0) !== (a.matchedKeywordCount || 0)) return (b.matchedKeywordCount || 0) - (a.matchedKeywordCount || 0);
    return a.originalIndex - b.originalIndex;
  });

const strongRows = positiveRows.filter(row => row.relevanceScore >= config.minStrongScore);
const weakRows = positiveRows.filter(row => row.relevanceScore < config.minStrongScore).slice(0, config.maxWeakNotes);
const selectedRows = unique([...strongRows, ...weakRows].map(row => row.itemId || row.contentHash || String(row.originalIndex)))
  .map(key => positiveRows.find(row => (row.itemId || row.contentHash || String(row.originalIndex)) === key))
  .filter(Boolean)
  .slice(0, config.maxRelevantNotes);

const relevantNotes = selectedRows.map(row => ({
  title: row.title,
  sourceTitle: row.sourceTitle,
  itemType: row.itemType,
  itemId: row.itemId,
  relativePath: row.relativePath,
  absolutePath: row.absolutePath,
  contentHash: row.contentHash,
  importance: row.importance,
  relevanceScore: row.relevanceScore,
  rawRelevanceScore: row.rawRelevanceScore,
  matchedKeywords: row.matchedKeywords,
  matchedKeywordCount: row.matchedKeywordCount,
  rankReason: row.rankReason,
  keywords: row.keywords,
  tags: row.tags,
  contentExcerpt: row.contentExcerpt
}));

const scoreBuckets = {
  strong: positiveRows.filter(row => row.relevanceScore >= config.minStrongScore).length,
  weak: positiveRows.filter(row => row.relevanceScore >= config.minScore && row.relevanceScore < config.minStrongScore).length,
  belowThreshold: scoredRows.filter(row => row.relevanceScore > 0 && row.relevanceScore < config.minScore).length,
  zero: scoredRows.filter(row => row.relevanceScore <= 0).length
};

const topRejectedRows = scoredRows
  .filter(row => row.relevanceScore > 0 && row.relevanceScore < config.minScore)
  .sort((a, b) => b.relevanceScore - a.relevanceScore)
  .slice(0, 5)
  .map(row => ({
    title: row.title,
    sourceTitle: row.sourceTitle,
    itemType: row.itemType,
    relevanceScore: row.relevanceScore,
    matchedKeywords: row.matchedKeywords,
    rankReason: row.rankReason
  }));

const { obsidianRows, ...lightInput } = input;

return [
  {
    json: {
      ...lightInput,
      contextFound: relevantNotes.length > 0,
      relevantNotes,
      selectedContextCount: relevantNotes.length,
      contextStats: {
        searchVersion: 'weighted-keyword-v2.1',
        query: question,
        queryKeywords: questionTokens,
        queryBigrams: questionBigrams,
        totalRows: rows.length,
        scoredRows: scoredRows.filter(row => row.relevanceScore > 0).length,
        selectedRows: relevantNotes.length,
        maxRelevantNotes: config.maxRelevantNotes,
        minScore: config.minScore,
        minStrongScore: config.minStrongScore,
        maxExcerptChars: config.maxExcerptChars,
        scoreBuckets,
        topSelectedRows: relevantNotes.map(note => ({
          title: note.title,
          itemType: note.itemType,
          importance: note.importance,
          relevanceScore: note.relevanceScore,
          matchedKeywords: note.matchedKeywords,
          rankReason: note.rankReason
        })),
        topRejectedRows
      }
    }
  }
];

const input = $input.first().json;
if (input.promptSecurityReady !== true || input.promptSecurity?.policyVersion !== 'chelsea_prompt_security_v3') { throw new Error('prompt_security_receipt_missing_or_invalid'); }

const DEFAULT_TIME_ZONE = 'Asia/Novosibirsk';
function normalizeTimeZone(value) {
  const zone = String(value || '').trim() || DEFAULT_TIME_ZONE;
  try { new Intl.DateTimeFormat('en-US', { timeZone: zone }).format(new Date(0)); return zone; }
  catch { return DEFAULT_TIME_ZONE; }
}
function buildUserTimeContext(timeZone, instant = new Date()) {
  const parts = new Intl.DateTimeFormat('ru-RU', {
    timeZone, year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'long',
    hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23', timeZoneName: 'longOffset'
  }).formatToParts(instant);
  const values = Object.fromEntries(parts.filter(part => part.type !== 'literal').map(part => [part.type, part.value]));
  return {
    timeZone,
    localDateTime: [values.year, '-', values.month, '-', values.day, ' ', values.hour, ':', values.minute, ':', values.second].join(''),
    weekday: values.weekday || '',
    utcOffset: values.timeZoneName || '',
    utcIso: instant.toISOString()
  };
}
const timeZone = normalizeTimeZone(input.timeZone);
const userTimeContext = buildUserTimeContext(timeZone);
const userTimeBlock = [
  'Часовой пояс: ' + userTimeContext.timeZone,
  'Текущее локальное время: ' + userTimeContext.localDateTime,
  'День недели: ' + userTimeContext.weekday,
  'Смещение: ' + userTimeContext.utcOffset,
  'Тот же момент в UTC: ' + userTimeContext.utcIso
].join('\n');

const question = String(input.question || '').trim();
const relevantNotes = Array.isArray(input.relevantNotes) ? input.relevantNotes : [];
const contextFound = Boolean(input.contextFound && relevantNotes.length > 0);
const chatHistory = Array.isArray(input.chatHistory) ? input.chatHistory : [];
const selectedMemoryBlock = String(input.selectedMemoryBlock || 'Релевантной истории диалога для текущего вопроса нет.').trim();
const selectedUserProfileMemoryBlock = String(input.selectedUserProfileMemoryBlock || 'Релевантной профильной памяти для текущего запроса нет.').trim();
const stateSummaryBlock = String(input.stateSummaryBlock || '\u0410\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u0430\u044f \u0441\u0432\u043e\u0434\u043a\u0430 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f \u043f\u043e\u043a\u0430 \u043d\u0435 \u0441\u0444\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u0430\u043d\u0430.').trim();
const chelseaSoulBlock = String(input.chelseaSoulBlock || 'Душа Челси для этого пользователя не найдена, используй базовый характер Челси.').trim();
const chelseaSoul = input.chelseaSoul || {};
const tagGuidanceBlock = String(input.tagGuidanceBlock || 'Дополнительные теги базы для уточнения вопроса не выбирались.').trim();
const tagGuidanceStats = input.tagGuidanceStats || {};
const selectedKnowledgeTags = Array.isArray(input.selectedKnowledgeTags) ? input.selectedKnowledgeTags : [];
