function cleanText(value) {
  return String(value || '')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();
}

function cutText(value, maxChars) {
  const text = cleanText(value);
  if (text.length <= maxChars) return text;
  return text.slice(0, maxChars).trim() + ' ...';
}

function compactList(value, limit = 12) {
  if (!Array.isArray(value)) return '';
  return value
    .map(v => String(v || '').trim())
    .filter(Boolean)
    .slice(0, limit)
    .join(', ');
}

function compactRelatedPeople(value, limit = 6) {
  if (!Array.isArray(value)) return '';
  return value
    .map(p => {
      if (!p || typeof p !== 'object') return String(p || '').trim();
      const name = cleanText(p.displayName || p.name || p.personId || p.id || '');
      const aliases = compactList(p.aliases || [], 6);
      const id = cleanText(p.personId || p.id || '');
      return [name, aliases ? `алиасы: ${aliases}` : '', id ? `id: ${id}` : ''].filter(Boolean).join(' | ');
    })
    .filter(Boolean)
    .slice(0, limit)
    .join('; ');
}
function buildNoteBlock(note, index) {
  const title = cleanText(note.title || `Заметка ${index + 1}`);
  const sourceTitle = cleanText(note.sourceTitle || '');
  const itemType = cleanText(note.itemType || '');
  const importance = cleanText(note.importance || '');
  const relativePath = cleanText(note.relativePath || '');
  const score = note.relevanceScore === undefined ? '' : String(note.relevanceScore);
  const foundByQueries = compactList(note.foundByQueries, 6);
  const matchedKeywords = compactList(note.matchedKeywords, 16);
  const keywords = compactList(note.keywords, 12);
  const tags = compactList(note.tags, 12);
  const pointType = cleanText(note.pointType || '');
  const personId = cleanText(note.personId || '');
  const displayName = cleanText(note.displayName || '');
  const aliases = compactList(note.aliases, 10);
  const primaryPersonId = cleanText(note.primaryPersonId || '');
  const relatedPeople = compactRelatedPeople(note.relatedPeople, 6);
  const personResolutionStatus = cleanText(note.personResolutionStatus || '');
  const rankReason = cleanText(note.rankReason || '');
  const content = cutText(note.contentExcerpt || note.content || '', maxNoteChars);

  const meta = [
    sourceTitle ? `Источник: ${sourceTitle}` : '',
    itemType ? `Тип: ${itemType}` : '',
    pointType ? `Тип точки: ${pointType}` : '',
    personId ? `Person ID: ${personId}` : '',
    displayName ? `Имя человека: ${displayName}` : '',
    aliases ? `Прозвища/алиасы: ${aliases}` : '',
    primaryPersonId ? `Основной связанный человек: ${primaryPersonId}` : '',
    relatedPeople ? `Связанные люди: ${relatedPeople}` : '',
    personResolutionStatus ? `Статус распознавания человека: ${personResolutionStatus}` : '',
    importance ? `Важность: ${importance}` : '',
    score ? `Релевантность: ${score}` : '',
    foundByQueries ? `Найдено по запросам: ${foundByQueries}` : '',
    matchedKeywords ? `Совпавшие слова: ${matchedKeywords}` : '',
    keywords ? `Ключевые слова заметки: ${keywords}` : '',
    tags ? `Теги: ${tags}` : '',
    rankReason ? `Причина выбора: ${rankReason}` : '',
    relativePath ? `Путь: ${relativePath}` : ''
  ].filter(Boolean).join(' | ');

  return `[${index + 1}] ${title}\n${meta}\n${content}`.trim();
}

