function isErrorRow(row) {
  const text = JSON.stringify(row || {}).toLowerCase();
  return Boolean(row?.error || row?.message?.includes?.('error') || row?.name === 'NodeApiError' || text.includes('could not') || text.includes('not found'));
}

function toTime(value) {
  const text = safeString(value);
  const timestamp = Date.parse(text);
  if (!Number.isNaN(timestamp)) return timestamp;
  const numeric = Number(value || 0);
  if (numeric > 0) return numeric > 9999999999 ? numeric : numeric * 1000;
  return 0;
}

