function tryParseJson(value) {
  if (typeof value !== 'string') return value;
  const trimmed = value.trim();
  if (!trimmed.startsWith('{') && !trimmed.startsWith('[')) return value;
  try { return JSON.parse(trimmed); } catch (error) { return value; }
}

function safeString(value, limit = 0) {
  const text = String(value ?? '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
  return limit > 0 ? text.slice(0, limit).trim() : text;
}

function safeArray(value) {
  if (Array.isArray(value)) return value.map(v => String(v || '').trim()).filter(Boolean);
  const text = String(value || '').trim();
  if (!text) return [];
  try {
    const parsed = JSON.parse(text);
    if (Array.isArray(parsed)) return parsed.map(v => String(v || '').trim()).filter(Boolean);
  } catch (error) {}
  return text.split(/[;,|#\n]/g).map(v => v.trim()).filter(Boolean);
}

function safeObjectArray(value) {
  if (Array.isArray(value)) return value;
  const text = String(value || '').trim();
  if (!text) return [];
  try { const parsed = JSON.parse(text); return Array.isArray(parsed) ? parsed : []; } catch (error) { return []; }
}
function normalizedTriggerText(value) {
  return safeString(value, 12000).normalize('NFKC').toLocaleLowerCase('ru-RU').replace(/ё/g, 'е')
    .replace(/[«»„“”"']/g, '').replace(/[^a-zа-я0-9]+/giu, ' ').replace(/\s+/g, ' ').trim();
}
function matchTriggeredInstruction(payload, question) {
  if (safeString(payload.memoryKind).toLowerCase() !== 'triggered_instruction') return null;
  if (safeString(payload.instructionStatus || payload.status || 'active').toLowerCase() !== 'active') return null;
  const normalizedQuestion = normalizedTriggerText(question);
  if (!normalizedQuestion || /(?:созда|сдела|сохран|обнов|измени|удали).{0,40}(?:инструкц|протокол|памятк|триггер)/u.test(normalizedQuestion)) return null;
  const blocks = safeObjectArray(payload.responseBlocks || payload.response_blocks);
  const blockById = new Map(blocks.map(block => [safeString(block?.blockId || block?.id).toLowerCase(), block]));
  for (const rule of safeObjectArray(payload.triggerRules || payload.trigger_rules)) {
    const phrases = uniqueStrings([...safeArray(rule?.phrases), ...safeArray(rule?.aliases)], 40);
    for (const phrase of phrases) {
      const normalizedPhrase = normalizedTriggerText(phrase);
      if (normalizedPhrase.length < 3 || !normalizedQuestion.includes(normalizedPhrase)) continue;
      const phraseStart = normalizedQuestion.indexOf(normalizedPhrase);
      const prefix = normalizedQuestion.slice(Math.max(0, phraseStart - 18), phraseStart);
      if (rule?.requireCurrentEvent !== false && /(?:если|когда|буду|напишу|собираюсь|не)\s*$/u.test(prefix)) continue;
      if (rule?.requireFirstPerson === true && !/(?:^|\s)(?:я|мне|мы)(?:\s|$)/u.test(normalizedQuestion)) continue;
      const responseBlockId = safeString(rule?.responseBlockId || rule?.response_block_id).toLowerCase();
      const block = blockById.get(responseBlockId);
      if (!block || !safeString(block.text || block.content || block.responseText, 12000)) continue;
      return {
        triggerId: safeString(rule?.triggerId || rule?.id, 120).toLowerCase(),
        responseBlockId,
        matchedPhrase: phrase,
        timeHint: safeString(rule?.timeHint || rule?.time_hint, 80),
        responseText: safeString(block.text || block.content || block.responseText, 12000),
        responseTitle: safeString(block.title || '', 240)
      };
    }
  }
  return null;
}
function cleanContent(value, maxChars = 2400) {
  return String(value || '')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim()
    .slice(0, maxChars);
}

function shortJson(value) {
  try { return JSON.stringify(value).slice(0, 5000); } catch (error) { return String(value || '').slice(0, 5000); }
}

function uniqueStrings(values, limit = 20) {
  const out = [];
  const seen = new Set();
  for (const value of values || []) {
    const text = safeString(value);
    if (!text) continue;
    const key = text.toLowerCase().replace(/ё/g, 'е');
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(text);
    if (out.length >= limit) break;
  }
  return out;
}

function payloadContent(payload, maxChars) {
  const parts = [];
  const summary = safeString(payload.summary || payload.compressedSummary || payload.definition || payload.explanation || '');
  const retrievalText = safeString(payload.retrievalText || payload.searchText || '');
  const text = safeString(payload.text || payload.content || payload.markdown || payload.contentPreview || '');
  const sourceExcerpts = safeArray(payload.sourceExcerpts || payload.source_excerpts).slice(0, 6);
  const queryAliases = safeArray(payload.queryAliases || payload.query_aliases).slice(0, 12);

  if (summary) parts.push(`Кратко: ${summary}`);
  if (retrievalText) parts.push(`Текст для поиска: ${retrievalText}`);
  if (text && text !== retrievalText && text !== summary) parts.push(text);
  if (queryAliases.length) parts.push(`Поисковые формулировки: ${queryAliases.join('; ')}`);
  if (sourceExcerpts.length) parts.push(`Доказательная база:\n${sourceExcerpts.map(x => `— ${x}`).join('\n')}`);

  return cleanContent(uniqueStrings(parts, 8).join('\n\n'), maxChars);
}

