  }
  return '';
}

function precedingAssistantContext(source) {
  const explicit = safeString(source.precedingAssistantQuestion || '', 4000);
  if (explicit) return explicit;

  let history = source.chatHistory;
  if (typeof history === 'string') {
    try { history = JSON.parse(history); }
    catch (error) { history = []; }
  }
  if (!Array.isArray(history)) return '';

  for (let index = history.length - 1; index >= 0; index--) {
    const entry = history[index];
    if (!entry || safeString(entry.role || '', 40).toLowerCase() !== 'assistant') continue;
    const text = assistantContextText(entry);
    if (text) return text;
  }
  return '';
}

